"""Control-flow and loading exceptions for Mantle hooks."""

from __future__ import annotations

from typing import Optional

from rasa.shared.exceptions import RasaException


class HookControlFlow(Exception):
    """Intentional signal from a modify hook. Not a bug."""


class HookRejection(HookControlFlow):
    """The hook decided this action must not proceed."""

    def __init__(
        self,
        reason: str,
        response_message: Optional[str] = None,
    ) -> None:
        """Create a rejection.

        ``response_message`` is the name of a response declared by the bot,
        not free-form text. The framework resolves and sends that response when
        the insertion point supports user-visible rejection feedback.
        """
        super().__init__(reason)
        self.reason = reason
        self.response_message = response_message


class RetryModel(HookControlFlow):
    """Discard the current result and steer the model loop with feedback.

    ``feedback`` is an engine-only system note for the next model request. It
    must not be stored on the tracker and must never be uttered to the user.
    """

    def __init__(self, feedback: str) -> None:
        super().__init__(feedback)
        self.feedback = feedback


class HookLoadingError(RasaException):
    """A hook module in the model archive could not be imported."""


class HookExecutionError(RasaException):
    """A fail-closed modify hook crashed or timed out."""


class DuplicateModifierError(RasaException):
    """More than one modify hook registered for the same point."""
